 protected:
     struct BlockData {
+        // Keep the symbol table alive until after IR children are destroyed.
+        // IRNode::~IRNode first destroys child expressions/statements and only then destroys
+        // NodeData. If BlockData released its symbol table in NodeData cleanup, Variable objects
+        // could be freed before VariableReference children run their destructors, causing UAF in
+        // Variable::referenceDestroyed.
+        ~BlockData() = default;
+
+        bool fIsScope;
         std::shared_ptr<SymbolTable> fSymbolTable;
         // if isScope is false, this is just a group of statements rather than an actual
         // language-level block. This allows us to pass around multiple statements as if they were a
         // single unit, with no semantic impact.
-        bool fIsScope;
     };

